mapper.select:
SELECT , FALSE AS archived
FROM LOG_BIZ log_data
WHERE log_data.ID = #{id}
AND log_data.TENANT_ID = #{tenantId}
UNION ALL
SELECT , TRUE AS archived
FROM LOG_BIZ_ARCHIVE log_data
WHERE log_data.ID = #{id}
AND log_data.TENANT_ID = #{tenantId}
LIMIT 1

SELECT COALESCE(SUM(log_count), 0)
FROM (
    SELECT COUNT(*) AS log_count
    FROM LOG_BIZ
    WHERE 1 = 1
    AND TENANT_ID = #{tenantId}
    AND OPERATE_DATETIME >= #{begin}
    AND OPERATE_DATETIME <= #{end}
    AND OPERATOR LIKE CONCAT('%', #{operator}, '%')
    AND OPERATE_TYPE = #{operateType}
    AND M_CODE = #{mCode}
    AND B_ID = #{bId}

        UNION ALL
        SELECT COUNT(*) AS log_count
        FROM LOG_BIZ_ARCHIVE
        WHERE 1 = 1
        AND TENANT_ID = #{tenantId}
        AND OPERATE_DATETIME >= #{begin}
        AND OPERATE_DATETIME <= #{end}
        AND OPERATOR LIKE CONCAT('%', #{operator}, '%')
        AND OPERATE_TYPE = #{operateType}
        AND M_CODE = #{mCode}
        AND B_ID = #{bId}

) counts

SELECT *
FROM (
    SELECT , FALSE AS archived
    FROM LOG_BIZ log_data
    WHERE 1 = 1
    AND log_data.TENANT_ID = #{tenantId}
    AND log_data.OPERATE_DATETIME >= #{begin}
    AND log_data.OPERATE_DATETIME <= #{end}
    AND log_data.OPERATOR LIKE CONCAT('%', #{operator}, '%')
    AND log_data.OPERATE_TYPE = #{operateType}
    AND log_data.M_CODE = #{mCode}
    AND log_data.B_ID = #{bId}

        UNION ALL
        SELECT , TRUE AS archived
        FROM LOG_BIZ_ARCHIVE log_data
        WHERE 1 = 1
        AND log_data.TENANT_ID = #{tenantId}
        AND log_data.OPERATE_DATETIME >= #{begin}
        AND log_data.OPERATE_DATETIME <= #{end}
        AND log_data.OPERATOR LIKE CONCAT('%', #{operator}, '%')
        AND log_data.OPERATE_TYPE = #{operateType}
        AND log_data.M_CODE = #{mCode}
        AND log_data.B_ID = #{bId}

) logs
ORDER BY OPERATE_DATETIME DESC, ID DESC
LIMIT #{limit} OFFSET #{offset}
